		new BalanceText(InterfaceID.ChatLeft.TEXT, "mta_alch", BalanceTextParser.before("Alchemist", PIZAZZ)),
		new BalanceText(InterfaceID.ChatLeft.TEXT, "mta_ench", BalanceTextParser.before("Enchantment", PIZAZZ)),
