/**
 * Everything the planner needs to know about the player.
 */
@Getter
@Builder
public class PlannerInput
{
	/** Collection log slots already obtained, by item name. */
	@Builder.Default
	private final Set<String> owned = Collections.emptySet();

	/**
	 * Slots the player wants: the goal. Null plans every missing slot (used for whole-page totals).
	 */
	@Builder.Default
	private final Set<String> wanted = null;

	/** Current amount of each currency, by currency id. */
	@Builder.Default
	private final Map<String, Long> balances = Collections.emptyMap();

	/** Extra currency targets outside the log (e.g. sawmill vouchers), by currency id. */
	@Builder.Default
	private final Map<String, Long> extraGoals = Collections.emptyMap();

	/**
	 * Shop picked by the player for items sold in more than one place (item name -> activity id).
	 * Items without a pick are left out of the costs; there is no default.
	 */
	@Builder.Default
	private final Map<String, String> preferredActivity = Collections.emptyMap();

	@Builder.Default
	private final AccountMode accountMode = AccountMode.MAIN;

	/** Items the player will sell back to their shop once the slot is logged. */
	@Builder.Default
	private final Set<String> sellBack = Collections.emptySet();

	/** The player wears Karamja gloves at TzHaar: cheaper prices and better sell-backs. */
	@Builder.Default
	private final boolean karamjaGloves = false;

	public boolean isSellBack(String item)
	{
		return sellBack.contains(item);
	}

	public boolean isOwned(String item)
	{
		return owned.contains(item);
	}

	public boolean isWanted(String item)
	{
		return wanted == null || wanted.contains(item);
	}

	public long getBalance(String currency)
	{
		return balances.getOrDefault(currency, 0L);
	}
}

package com.rewardshopplanner.data;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * A minigame or other content with its own collection log page.
 */
@Getter
public class Activity
{
	private String id;
	private String name;
	private String clogTab;
	private String clogPage;
	/** Currency ids spent on this page's purchasable slots. */
	private List<String> currencies;
	/** Every item on the collection log page, purchasable or not. */
	private List<String> clogItems;
	/** Item id of each entry in {@link #clogItems}, same order; 0 when unknown. */
	private int[] clogItemIds;
	/** Cost of buying every purchasable slot on the page, as generated (for reference). */
	private Map<String, Integer> totalCost;
	/** Map regions where the on-screen progress shows; empty when it shows after earning instead. */
	private int[] regions;
	/** Lowest plane that counts in those regions (1 keeps Rooftop Agility to the rooftops). */
	private int minPlane;
	/** Finer places than whole regions: polygons walked in game, maybe for some currencies only. */
	private List<Area> areas;
	private String notes;

	/** Whether the activity has a place at all; without one its progress shows after earning instead. */
	public boolean hasPlace()
	{
		return (regions != null && regions.length > 0) || (areas != null && !areas.isEmpty());
	}

	/**
	 * The currencies to show for a player on this tile: null when not at the activity, empty for
	 * all of them, or the ones of the area the player is in.
	 */
	public Set<String> currenciesAt(int regionId, int x, int y, int plane)
	{
		if (regions != null && plane >= minPlane)
		{
			for (int region : regions)
			{
				if (region == regionId)
				{
					return Collections.emptySet();
				}
			}
		}
		Set<String> shown = null;
		for (Area area : areas == null ? Collections.<Area>emptyList() : areas)
		{
			if (!area.contains(regionId, x, y, plane))
			{
				continue;
			}
			if (area.getCurrencies() == null || area.getCurrencies().isEmpty())
			{
				return Collections.emptySet();
			}
			shown = shown == null ? new LinkedHashSet<>() : shown;
			shown.addAll(area.getCurrencies());
		}
		return shown;
	}
}

package com.rewardshopplanner.data;

import java.util.List;
import lombok.Getter;

/**
 * A place where an activity's on-screen progress shows: whole map regions, or a polygon of tiles
 * walked in game (corners in order). It can be limited to some currencies, e.g. the Mining Guild
 * shows only unidentified minerals.
 */
@Getter
public class Area
{
	/** Plane the area is on; null for any. */
	private Integer plane;
	private int[] regions;
	/** Polygon corners as [x, y] tiles; the tiles on its edges are inside. */
	private int[][] points;
	/** Currencies shown here; null or empty for all of the activity's. */
	private List<String> currencies;

	public boolean contains(int regionId, int x, int y, int tilePlane)
	{
		if (plane != null && plane != tilePlane)
		{
			return false;
		}
		if (regions != null)
		{
			for (int region : regions)
			{
				if (region == regionId)
				{
					return true;
				}
			}
		}
		return points != null && points.length >= 3 && inPolygon(x, y);
	}

	private boolean inPolygon(int x, int y)
	{
		boolean inside = false;
		for (int i = 0, j = points.length - 1; i < points.length; j = i++)
		{
			int x1 = points[i][0];
			int y1 = points[i][1];
			int x2 = points[j][0];
			int y2 = points[j][1];
			if (onSegment(x, y, x1, y1, x2, y2))
			{
				return true;
			}
			// ray casting to the east
			if ((y1 > y) != (y2 > y) && x < (double) (x2 - x1) * (y - y1) / (y2 - y1) + x1)
			{
				inside = !inside;
			}
		}
		return inside;
	}

	/** Whether the tile lies on the edge between two corners (within half a tile). */
	private static boolean onSegment(int x, int y, int x1, int y1, int x2, int y2)
	{
		double dx = x2 - x1;
		double dy = y2 - y1;
		double length = dx * dx + dy * dy;
		double t = length == 0 ? 0 : Math.max(0, Math.min(1, ((x - x1) * dx + (y - y1) * dy) / length));
		double px = x1 + t * dx - x;
		double py = y1 + t * dy - y;
		return px * px + py * py <= 0.25;
	}
}

