	@Setter
	private PageProgress.Bar bar;
	/** Asked each time the box is drawn: a spell sprite may only arrive after the box was added. */
	private final Supplier<BufferedImage> icon;

	public ProgressInfoBox(Supplier<BufferedImage> icon, Plugin plugin, String key)
	{
		super(null, plugin);
		this.icon = icon;
		this.key = key;
	}

	@Override
	public BufferedImage getImage()
	{
		return icon.get();
	}

	/** "have/need" doesn't fit under an icon, so the box shows the percentage; the tooltip has the numbers. */
	@Override
	public String getText()
	{
		if (bar.getHave() == null)
		{
			return "?";
		}
		return Math.min(100, (int) Math.floor(100.0 * bar.getHave() / bar.getNeed())) + "%";
	}

	@Override
	public Color getTextColor()
	{
		return bar.isDone() ? ColorScheme.PROGRESS_COMPLETE_COLOR : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		String have = bar.getHave() == null ? "unknown" : QuantityFormatter.formatNumber(bar.getHave());
		String summary = ProgressOverlay.summary(page);
		return page.getActivity().getName() + (summary.isEmpty() ? "" : " (" + summary + ")")
			+ "</br>" + bar.getName() + ": " + have + " / " + QuantityFormatter.formatNumber(bar.getNeed());
	}
}

package com.rewardshopplanner.overlay;

import com.rewardshopplanner.RewardShopPlannerConfig;
import com.rewardshopplanner.data.Currency;
import com.rewardshopplanner.data.RewardData;
import com.rewardshopplanner.ui.ItemIcons;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Locale;
import java.util.function.Supplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * The goal's progress on the game screen for the activity being played: the page name with
 * "N left · M ready", then each currency as "have / need", with a slim bar in the Bars style.
 */
public class ProgressOverlay extends OverlayPanel
{
	private static final int WIDTH = 200;
	private static final Color MUTED = new Color(0xb0b0b0);
	private static final Color GOOD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	private static final int ICON_SIZE = 16;
	private static final int ICON_GAP = 4;
	private static final Runnable NOTHING = () -> { };

	private final RewardShopPlannerConfig config;
	private final ItemIcons icons;
	private final RewardData data;
	private final Supplier<List<PageProgress>> pages;

	public ProgressOverlay(Plugin plugin, RewardShopPlannerConfig config, ItemIcons icons, RewardData data, Supplier<List<PageProgress>> pages)
	{
		super(plugin);
		this.config = config;
		this.icons = icons;
		this.data = data;
		this.pages = pages;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || config.overlayStyle() == RewardShopPlannerConfig.OverlayStyle.ICONS)
		{
			return null;
		}
		List<PageProgress> shown = pages.get();
		if (shown.isEmpty())
		{
			return null;
		}
		boolean bars = config.overlayStyle() == RewardShopPlannerConfig.OverlayStyle.BARS;
		boolean first = true;
		for (PageProgress page : shown)
		{
			if (!first)
			{
				panelComponent.getChildren().add(LineComponent.builder().build());
			}
			first = false;
			String name = page.getActivity().getName();
			String summary = summary(page);
			Color summaryColor = page.getReady() > 0 ? GOOD : MUTED;
			// long names (Mage Training Arena) push the summary onto its own line instead of wrapping both
			int needed = graphics.getFontMetrics(FontManager.getRunescapeBoldFont()).stringWidth(name)
				+ graphics.getFontMetrics(FontManager.getRunescapeSmallFont()).stringWidth(summary) + 12;
			boolean fits = needed <= WIDTH - 8;
			panelComponent.getChildren().add(LineComponent.builder()
				.left(name)
				.leftFont(FontManager.getRunescapeBoldFont())
				.right(fits ? summary : "")
				.rightColor(summaryColor)
				.build());
			if (!fits)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.right(summary)
					.rightColor(summaryColor)
					.build());
			}
			for (PageProgress.Bar bar : page.getBars())
			{
				BufferedImage icon = smallIcon(bar.getCurrencyId());
				int room = WIDTH - 8 - (icon == null ? 0 : ICON_SIZE + ICON_GAP);
				// full numbers when they fit next to the name, else 4,666 / 75K so the line doesn't wrap
				String amounts = amounts(bar, false);
				int width = graphics.getFontMetrics(FontManager.getRunescapeSmallFont()).stringWidth(bar.getName() + amounts) + 12;
				if (width > room)
				{
					amounts = amounts(bar, true);
				}
				LayoutableRenderableEntity row = LineComponent.builder()
					.left(bar.getName())
					.leftColor(MUTED)
					.right(amounts)
					.rightColor(bar.isDone() ? GOOD : Color.WHITE)
					.build();
				if (bars)
				{
					ThinBarComponent thin = new ThinBarComponent();
					thin.setFraction(bar.getHave() == null ? 0 : (double) bar.getHave() / bar.getNeed());
					thin.setColor(bar.isDone() ? GOOD : ACCENT);
					row = SplitComponent.builder().first(row).second(thin)
						.orientation(ComponentOrientation.VERTICAL).gap(new Point(0, 1)).build();
				}
				if (icon != null)
				{
					// the currency's icon on the left, like the resin bars of the Mastering Mixology plugin
					row = SplitComponent.builder().first(new ImageComponent(icon)).second(row)
						.orientation(ComponentOrientation.HORIZONTAL).gap(new Point(ICON_GAP, 0)).build();
				}
				panelComponent.getChildren().add(row);
			}
		}
		return super.render(graphics);
	}

	/** The currency's icon shrunk to fit a line; null when it has none (yet: a sprite may be loading). */
	private BufferedImage smallIcon(String currencyId)
	{
		Currency currency = data.getCurrencies().get(currencyId);
		BufferedImage image = currency == null ? null : icons.currency(currency, NOTHING);
		if (image == null || image.getWidth() <= 0 || image.getHeight() <= 0)
		{
			return null;
		}
		// centred on a fixed square, so every currency's text starts at the same place
		BufferedImage scaled = ImageUtil.resizeImage(image, ICON_SIZE, ICON_SIZE, true);
		BufferedImage square = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = square.createGraphics();
		g.drawImage(scaled, (ICON_SIZE - scaled.getWidth()) / 2, (ICON_SIZE - scaled.getHeight()) / 2, null);
		g.dispose();
		return square;
	}

	static String amounts(PageProgress.Bar bar, boolean compact)
	{
		return (bar.getHave() == null ? "?" : format(bar.getHave(), compact)) + " / " + format(bar.getNeed(), compact);
	}

	/** 4,666 stays whole; compact shortens from 10,000 up: 75K, 12.4K, 1.25M. */
	static String format(long value, boolean compact)
	{
		if (!compact || value < 10_000)
		{
			return QuantityFormatter.formatNumber(value);
		}
		if (value < 1_000_000)
		{
			return trim(String.format(Locale.US, "%.1f", value / 1_000.0)) + "K";
		}
		return trim(String.format(Locale.US, "%.2f", value / 1_000_000.0)) + "M";
	}

	private static String trim(String number)
	{
		return number.contains(".") ? number.replaceAll("0+$", "").replaceAll("\\.$", "") : number;
	}

	/** "2 left · 1 ready", or nothing when only an extra goal keeps the page on screen. */
	static String summary(PageProgress page)
	{
		if (page.getLeft() == 0)
		{
			return "";
		}
		return page.getLeft() + " left · " + page.getReady() + " ready";
	}
}

package com.rewardshopplanner.overlay;

import com.rewardshopplanner.RewardShopPlannerConfig;
import com.rewardshopplanner.data.Activity;
import com.rewardshopplanner.data.Currency;
import com.rewardshopplanner.data.Reward;
import com.rewardshopplanner.data.RewardData;
import com.rewardshopplanner.ui.ItemIcons;
import com.rewardshopplanner.ui.PanelModel;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

/**
 * Decides which pages the on-screen progress shows: the activity you're standing in, or, for
 * activities without a fixed place, the ones whose currency you earned recently.
 */
@Slf4j
public class ProgressTracker
{

	private final Plugin plugin;
	private final RewardShopPlannerConfig config;
	private final ConfigManager configManager;
	private final ItemIcons icons;
	private static final Runnable NOTHING = () -> { };
	private final InfoBoxManager infoBoxManager;
	private final RewardData data;
	/** Each activity's currencies plus the counters its milestones use (chompy kills, LMS wins). */
	private final Map<String, Set<String>> activityCurrencies = new HashMap<>();

	private volatile PanelModel model;
	/**
	 * Activities the player is at, with the currencies to show there (empty for all of them);
	 * replaced as a whole each tick.
	 */
	private volatile Map<String, Set<String>> here = Collections.emptyMap();
	/** When each currency was last earned, in millis. */
	private final Map<String, Long> lastEarned = new ConcurrentHashMap<>();
	/** Item currencies in the inventory, and in the bank and Forestry kit, at the end of the last tick. */
	private Map<String, Long> lastInventory;
	private Map<String, Long> lastStored;
	/** Item currencies picked up from the ground this tick. */
	private final Map<String, Long> pickups = new HashMap<>();
	/** Non-item currencies already read from the game this session. */
	private final Set<String> readThisSession = new HashSet<>();
	/** The region last logged, so only changes are logged. */
	private int loggedRegion = -1;
	/** Icons-style boxes by "activity:currency"; client thread only. */
	private final Map<String, ProgressInfoBox> infoBoxes = new HashMap<>();

	public ProgressTracker(Plugin plugin, RewardShopPlannerConfig config, ConfigManager configManager, ItemIcons icons,
		InfoBoxManager infoBoxManager, RewardData data)
	{
		this.plugin = plugin;
		this.config = config;
		this.configManager = configManager;
		this.icons = icons;
		this.infoBoxManager = infoBoxManager;
		this.data = data;
		for (Activity activity : data.getActivities().values())
		{
			Set<String> currencies = new LinkedHashSet<>();
			if (activity.getCurrencies() != null)
			{
				currencies.addAll(activity.getCurrencies());
			}
			for (String item : activity.getClogItems())
			{
				Reward reward = data.getReward(item);
				if (reward != null && reward.getMilestone() != null && reward.getMilestone().getCounter() != null)
				{
					currencies.add(reward.getMilestone().getCounter());
				}
			}
			activityCurrencies.put(activity.getId(), currencies);
		}
	}

	/** The latest plan and balances. */
	public void update(PanelModel model)
	{
		this.model = model;
	}


	public void onLogout()
	{
		startSession();
		lastEarned.clear();
		here = Collections.emptyMap();
	}

	private void startSession()
	{
		lastInventory = null;
		lastStored = null;
		readThisSession.clear();
		pickups.clear();
	}

	/**
	 * A currency the game reports as a number (points in a var or on a shop screen, a kill count).
	 * The first reading of a session only sets the baseline: it may catch up on play elsewhere.
	 */
	public void onGameValue(String currency, Long before, long now)
	{
		boolean first = readThisSession.add(currency);
		if (!first && before != null && now > before)
		{
			earned(currency);
		}
	}

	/** Whether the currency was earned since the session started; for tests. */
	boolean wasEarned(String currency)
	{
		return lastEarned.containsKey(currency);
	}

	/** Something that is always a real gain, like a chompy kill message. */
	public void earned(String currency)
	{
		lastEarned.put(currency, System.currentTimeMillis());
	}

	/** An item currency picked up from the ground next to the player (the player's own drop). */
	public void onPickup(String currency, long quantity)
	{
		pickups.merge(currency, quantity, Long::sum);
	}

	/**
	 * Item currencies count as earned only when the inventory gains them, minus what left the bank
	 * or Forestry kit in the same tick (a withdrawal) and what was picked up from the ground. Reading
	 * the bank or kit never counts: it only shows what was already there.
	 */
	public void onItemCounts(Map<String, Long> inventory, Map<String, Long> stored)
	{
		if (lastInventory != null)
		{
			for (Map.Entry<String, Long> entry : inventory.entrySet())
			{
				String currency = entry.getKey();
				Long before = lastInventory.get(currency);
				if (before == null)
				{
					continue;
				}
				long gained = entry.getValue() - before;
				long withdrawn = Math.max(0, lastStored.getOrDefault(currency, 0L) - stored.getOrDefault(currency, 0L));
				if (gained - withdrawn - pickups.getOrDefault(currency, 0L) > 0)
				{
					earned(currency);
				}
			}
		}
		if (!inventory.isEmpty())
		{
			lastInventory = new HashMap<>(inventory);
			lastStored = new HashMap<>(stored);
		}
		pickups.clear();
	}

	/** Reads where the player is (instances map back to their real region) and refreshes the icons. */
	public void onGameTick(Client client)
	{
		Player player = client.getLocalPlayer();
		Map<String, Set<String>> at = new HashMap<>();
		if (player != null)
		{
			// like RuneLite's Discord plugin: instanced areas map back to their template region
			WorldPoint point = WorldPoint.fromLocalInstance(client, player.getLocalLocation());
			if (point != null)
			{
				for (Activity activity : data.getActivities().values())
				{
					Set<String> currencies = activity.currenciesAt(point.getRegionID(), point.getX(), point.getY(), point.getPlane());
					if (currencies != null)
					{
						at.put(activity.getId(), currencies);
					}
				}
				if (point.getRegionID() != loggedRegion)
				{
					// lets a player report the region of a spot where the progress should show but doesn't
					loggedRegion = point.getRegionID();
					log.debug("Reward Shop Planner: region {} at {}, activities {}", loggedRegion, point, at.keySet());
				}
			}
		}
		here = at;
		updateInfoBoxes();
	}

	/** The pages to show right now, in the data's order. */
	public List<PageProgress> shown()
	{
		PanelModel current = model;
		List<PageProgress> pages = new ArrayList<>();
		if (current == null || !config.showOverlay())
		{
			return pages;
		}
		for (Activity activity : data.getActivities().values())
		{
			RewardShopPlannerConfig.OverlayMode mode = mode(activity);
			if (mode == RewardShopPlannerConfig.OverlayMode.OFF)
			{
				continue;
			}
			Set<String> currencies = here.get(activity.getId());
			if (mode == RewardShopPlannerConfig.OverlayMode.ALWAYS
				|| (currencies == null && !activity.hasPlace() && earnedRecently(activity)))
			{
				// always on screen, or earned recently somewhere: every currency of the page
				currencies = Collections.emptySet();
			}
			if (currencies == null)
			{
				continue;
			}
			PageProgress page = PageProgress.of(current, activity, currencies);
			if (page != null && !page.getBars().isEmpty())
			{
				pages.add(page);
			}
		}
		return pages;
	}

	public void shutDown()
	{
		infoBoxManager.removeIf(box -> box instanceof ProgressInfoBox);
		infoBoxes.clear();
		lastEarned.clear();
	}

	private RewardShopPlannerConfig.OverlayMode mode(Activity activity)
	{
		return modeOf(configManager.getConfiguration(RewardShopPlannerConfig.GROUP,
			RewardShopPlannerConfig.OVERLAY_KEY_PREFIX + activity.getId()));
	}

	/**
	 * The activity's setting as saved: an OverlayMode name, nothing (the default), or "true"/"false"
	 * from before it was a choice of three.
	 */
	static RewardShopPlannerConfig.OverlayMode modeOf(String saved)
	{
		if (saved == null || saved.equals("true"))
		{
			return RewardShopPlannerConfig.OverlayMode.AT_THE_ACTIVITY;
		}
		if (saved.equals("false"))
		{
			return RewardShopPlannerConfig.OverlayMode.OFF;
		}
		try
		{
			return RewardShopPlannerConfig.OverlayMode.valueOf(saved);
		}
		catch (IllegalArgumentException e)
		{
			return RewardShopPlannerConfig.OverlayMode.AT_THE_ACTIVITY;
		}
	}

	private boolean earnedRecently(Activity activity)
	{
		long window = config.overlayHideAfter() * 60_000L;
		long now = System.currentTimeMillis();
		for (String currency : activityCurrencies.getOrDefault(activity.getId(), Collections.emptySet()))
		{
			Long when = lastEarned.get(currency);
			if (when != null && (window == 0 || now - when < window))
			{
				return true;
			}
		}
		return false;
	}

	/** Keeps one info box per shown currency in the Icons style, and none otherwise. */
	private void updateInfoBoxes()
	{
		Map<String, PageProgress> wanted = new HashMap<>();
		Map<String, PageProgress.Bar> bars = new HashMap<>();
		if (config.overlayStyle() == RewardShopPlannerConfig.OverlayStyle.ICONS)
		{
			for (PageProgress page : shown())
			{
				for (PageProgress.Bar bar : page.getBars())
				{
					String key = page.getActivity().getId() + ":" + bar.getCurrencyId();
					wanted.put(key, page);
					bars.put(key, bar);
				}
			}
		}
		infoBoxes.entrySet().removeIf(entry ->
		{
			if (wanted.containsKey(entry.getKey()))
			{
				return false;
			}
			infoBoxManager.removeInfoBox(entry.getValue());
			return true;
		});
		for (Map.Entry<String, PageProgress> entry : wanted.entrySet())
		{
			ProgressInfoBox box = infoBoxes.get(entry.getKey());
			if (box == null)
			{
				PageProgress page = entry.getValue();
				Currency currency = data.getCurrencies().get(bars.get(entry.getKey()).getCurrencyId());
				box = new ProgressInfoBox(() -> iconFor(page, currency), plugin, entry.getKey());
				infoBoxes.put(entry.getKey(), box);
				box.setPage(entry.getValue());
				box.setBar(bars.get(entry.getKey()));
				infoBoxManager.addInfoBox(box);
			}
			box.setPage(entry.getValue());
			box.setBar(bars.get(entry.getKey()));
		}
	}

	/** The currency's icon (its item, stand-in item or spell sprite), else the first item sold on the page. */
	private BufferedImage iconFor(PageProgress page, Currency currency)
	{
		if (currency != null && (currency.getIconItem() != null || currency.getIconSpriteId() != null))
		{
			// a sprite may still be loading: the box asks again next frame
			return icons.currency(currency, NOTHING);
		}
		for (String item : page.getActivity().getClogItems())
		{
			Reward reward = data.getReward(item);
			if (reward != null && reward.getItemId() != null)
			{
				return icons.get(reward.getItemId(), NOTHING);
			}
		}
		return null;
	}
}

package com.rewardshopplanner.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * A slim progress bar for overlays: RuneLite's own bar is at least 16px tall with the text
 * inside, while this one sits under a line of text.
 */
class ThinBarComponent implements LayoutableRenderableEntity
{
	private static final Color BACKGROUND = new Color(255, 255, 255, 40);
	private static final int HEIGHT = 4;

	@Setter
	private double fraction;
	@Setter
	private Color color = Color.ORANGE;
	@Setter
	private Point preferredLocation = new Point();
	private int width = 129;
	@Getter
	private final Rectangle bounds = new Rectangle();

	/** The panel passes its width with a height of 0; the bar keeps its own height. */
	@Override
	public void setPreferredSize(Dimension size)
	{
		width = size.width;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int height = HEIGHT;
		int fill = (int) Math.round(width * Math.max(0, Math.min(1, fraction)));
		graphics.setColor(BACKGROUND);
		graphics.fillRect(preferredLocation.x + fill, preferredLocation.y, width - fill, height);
		graphics.setColor(color);
		graphics.fillRect(preferredLocation.x, preferredLocation.y, fill, height);
		bounds.setLocation(preferredLocation);
		bounds.setSize(width, height);
		return new Dimension(width, height);
	}
}

package com.rewardshopplanner.tracking;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads balances that game interfaces show as text (tags already removed). A pattern's first
 * group is the number; build them with {@link #after}, {@link #before} and {@link #first}.
 */
public final class BalanceTextParser
{
	private static final String NUMBER = "(\\d[\\d,]*)";

	/** Mahogany Homes, after each contract; the total is the current Carpenter point balance. */
	public static final Pattern MAHOGANY_CONTRACT =
		Pattern.compile("You have completed [\\d,]+ contracts with a total of " + NUMBER + " points");

	private BalanceTextParser()
	{
	}

	/** "Points: 1,245" or "Telekinetic: 0/30". */
	public static Pattern after(String label)
	{
		return Pattern.compile(Pattern.quote(label) + ":\\s*" + NUMBER);
	}

	/** "123 Enchantment", only when the text also contains {@code context} (to avoid stray matches). */
	public static Pattern before(String label, String context)
	{
		return Pattern.compile(NUMBER + "\\s+" + Pattern.quote(label) + "(?=.*" + Pattern.quote(context) + ")");
	}

	/** The first number in the text, for components that show only the value. */
	public static Pattern first()
	{
		return Pattern.compile(NUMBER);
	}

	/** The number the pattern finds, or null. */
	public static Long read(String text, Pattern pattern)
	{
		Matcher m = pattern.matcher(text);
		return m.find() ? Long.valueOf(m.group(1).replace(",", "")) : null;
	}
}

package com.rewardshopplanner.tracking;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads chompy bird kill counts from game text (tags already removed).
 */
public final class ChompyKillParser
{
	/**
	 * "Check kills" on an ogre bow: a dialog box says "You've killed a total of N chompy birds"
	 * and the chat says "You've scratched up a total of N chompy bird kills".
	 */
	private static final Pattern TOTAL = Pattern.compile(
		"You've (?:killed a total of ([\\d,]+) chompy birds|scratched up a total of ([\\d,]+) chompy bird kills)");
	/** Chat message for each kill. */
	private static final String NOTCH = "You scratch a notch on your bow for the chompy bird kill.";

	private ChompyKillParser()
	{
	}

	/** The total from a "Check kills" message, or null when the text is not one. */
	public static Long parseTotal(String text)
	{
		Matcher m = TOTAL.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String number = m.group(1) != null ? m.group(1) : m.group(2);
		return Long.parseLong(number.replace(",", ""));
	}

	public static boolean isKill(String text)
	{
		return NOTCH.equals(text.trim());
	}
}

package com.rewardshopplanner.tracking;

import com.rewardshopplanner.data.Activity;
import com.rewardshopplanner.data.RewardData;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Maps what the in-game collection log shows onto the item names used by the bundled data.
 */
public class CollectionLogMatcher
{
	/** One slot as drawn by the collection log interface. */
	@Value
	public static class Slot
	{
		int itemId;
		String name;
		boolean obtained;
	}

	private final RewardData data;

	public CollectionLogMatcher(RewardData data)
	{
		this.data = data;
	}

	public Activity activityForPage(String pageTitle)
	{
		for (Activity activity : data.getActivities().values())
		{
			if (activity.getClogPage().equalsIgnoreCase(pageTitle))
			{
				return activity;
			}
		}
		return null;
	}

	/**
	 * Resolves each slot of a page to a data item name, returning name -> obtained.
	 * Matching runs in passes so a weaker rule never takes an entry a stronger one would claim:
	 * item id, then item name (an item can have several ids, e.g. the Volcanic Mine prospector
	 * kit), then position when the page has the expected number of slots.
	 */
	public Map<String, Boolean> match(Activity activity, List<Slot> slots)
	{
		List<String> names = activity.getClogItems();
		int[] ids = activity.getClogItemIds();
		boolean[] used = new boolean[names.size()];
		int[] matched = new int[slots.size()];
		java.util.Arrays.fill(matched, -1);

		// 1. item id
		for (int i = 0; i < slots.size(); i++)
		{
			for (int j = 0; ids != null && j < ids.length; j++)
			{
				if (!used[j] && ids[j] != 0 && ids[j] == slots.get(i).getItemId())
				{
					used[j] = true;
					matched[i] = j;
					break;
				}
			}
		}
		// 2. exact name on this page
		for (int i = 0; i < slots.size(); i++)
		{
			String name = slots.get(i).getName();
			for (int j = 0; matched[i] < 0 && name != null && j < names.size(); j++)
			{
				if (!used[j] && names.get(j).equalsIgnoreCase(name))
				{
					used[j] = true;
					matched[i] = j;
				}
			}
		}
		// 3. position, when the page has the expected shape
		if (slots.size() == names.size())
		{
			for (int i = 0; i < slots.size(); i++)
			{
				if (matched[i] < 0 && !used[i])
				{
					used[i] = true;
					matched[i] = i;
				}
			}
		}

		Map<String, Boolean> result = new LinkedHashMap<>();
		for (int i = 0; i < slots.size(); i++)
		{
			if (matched[i] >= 0)
			{
				result.put(names.get(matched[i]), slots.get(i).isObtained());
			}
		}
		return result;
	}

	/**
	 * Resolves the item named in a "New item added to your collection log" message.
	 * In-game names drop the wiki's disambiguation ("Graceful hood" vs "Graceful hood (Varlamore)"),
	 * so ambiguous names return null and wait for the next page sync.
	 */
	public String resolveChatName(String itemName)
	{
		Set<String> candidates = new LinkedHashSet<>();
		for (Activity activity : data.getActivities().values())
		{
			for (String name : activity.getClogItems())
			{
				if (name.equalsIgnoreCase(itemName) || name.toLowerCase().startsWith(itemName.toLowerCase() + " ("))
				{
					candidates.add(name);
				}
			}
		}
		return candidates.size() == 1 ? candidates.iterator().next() : null;
	}
}

package com.rewardshopplanner.tracking;

import com.rewardshopplanner.calc.AccountMode;
import com.rewardshopplanner.data.Currency;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * Everything remembered about one character, saved to its RuneLite profile as JSON.
 */
@Getter
public class PlayerState
{
	/** Collection log slots obtained according to the game, by item name as used in the bundled data. */
	private Set<String> owned = new LinkedHashSet<>();
	/** Player corrections to {@link #owned} (item -> owned); dropped when the log is read again. */
	private Map<String, Boolean> ownedOverrides = new HashMap<>();
	/** Slots the player wants to get: the goal. */
	private Set<String> wanted = new LinkedHashSet<>();
	/** Collection log pages read from the game at least once. */
	private Set<String> syncedPages = new LinkedHashSet<>();
	/** Item currencies in the bank the last time it was open, by currency id. */
	private Map<String, Long> bankItems = new HashMap<>();
	/** Item currencies in the inventory, by currency id. */
	private Map<String, Long> inventoryItems = new HashMap<>();
	/** Item currencies stored in the Forestry kit (e.g. anima-infused bark), by currency id. */
	private Map<String, Long> forestryKitItems = new HashMap<>();
	/** Materials (logs, bars...) in the bank the last time it was open, by name; noted ones included. */
	private Map<String, Long> bankMaterials = new HashMap<>();
	/** Materials in the inventory, by name; noted ones included. */
	private Map<String, Long> inventoryMaterials = new HashMap<>();
	/** Logs in the log basket (shared with the Forestry basket), by name. */
	private Map<String, Long> logBasketMaterials = new HashMap<>();
	/** Currencies read from game vars, by currency id. */
	private Map<String, Long> varBalances = new HashMap<>();
	/**
	 * Balances typed by the player, or read from game text that no var holds (shop screens, chat).
	 * They take priority, until a tracked reading (item, var) for the same currency changes.
	 */
	private Map<String, Long> manualBalances = new HashMap<>();
	/** Shop picked for items sold in more than one place (item name -> activity id). */
	private Map<String, String> preferredActivity = new HashMap<>();
	private Map<String, Long> extraGoals = new LinkedHashMap<>();
	/** Items the player will sell back to their shop once logged; nothing is sold back by default. */
	private Set<String> sellBack = new LinkedHashSet<>();
	/** Whether the Karamja gloves reward was claimed, as last read from the game. */
	private boolean karamjaGlovesClaimed;
	/** The player's own answer to "do you wear Karamja gloves at TzHaar"; null follows the diary. */
	private Boolean karamjaGlovesChoice;
	/** Account type as last read from the game, so it stays right while logged out. */
	private AccountMode accountMode = AccountMode.MAIN;

	public PlayerState()
	{
	}

	public Set<String> getSellBack()
	{
		// older saved states have no sell-back set
		if (sellBack == null)
		{
			sellBack = new LinkedHashSet<>();
		}
		return sellBack;
	}

	public AccountMode getAccountMode()
	{
		// older saved states have no account type
		return accountMode == null ? AccountMode.MAIN : accountMode;
	}

	/** Records the account type read from the game; true when it changed. */
	public boolean setAccountMode(AccountMode mode)
	{
		if (getAccountMode() == mode)
		{
			return false;
		}
		accountMode = mode;
		return true;
	}

	public void setKaramjaGlovesClaimed(boolean claimed)
	{
		karamjaGlovesClaimed = claimed;
	}

	public void setKaramjaGlovesChoice(Boolean choice)
	{
		karamjaGlovesChoice = choice;
	}

	/** TzHaar prices use Karamja gloves: the player's choice, else whether the diary gloves were claimed. */
	public boolean wearsKaramjaGloves()
	{
		return karamjaGlovesChoice != null ? karamjaGlovesChoice : karamjaGlovesClaimed;
	}

	/** Owned slots after applying the player's corrections. */
	public Set<String> effectiveOwned()
	{
		Set<String> result = new LinkedHashSet<>(owned);
		for (Map.Entry<String, Boolean> override : ownedOverrides.entrySet())
		{
			if (override.getValue())
			{
				result.add(override.getKey());
			}
			else
			{
				result.remove(override.getKey());
			}
		}
		return result;
	}

	/**
	 * Records what the collection log says about a slot. The log is the source of truth, so any
	 * earlier correction by the player for that slot is dropped.
	 */
	public void setLogOwned(String item, boolean obtained)
	{
		if (obtained)
		{
			owned.add(item);
		}
		else
		{
			owned.remove(item);
		}
		ownedOverrides.remove(item);
	}

	/** The player marks a slot as owned or not; stored only when it differs from the log. */
	public void setOwnedByPlayer(String item, boolean ownedNow)
	{
		if (owned.contains(item) == ownedNow)
		{
			ownedOverrides.remove(item);
		}
		else
		{
			ownedOverrides.put(item, ownedNow);
		}
	}

	/**
	 * Current amount of a currency, or null when nothing is known about it.
	 */
	public Long balanceOf(Currency currency)
	{
		Long manual = manualBalances.get(currency.getId());
		if (manual != null)
		{
			return manual;
		}
		switch (currency.getSource())
		{
			case ITEM:
				Long bank = bankItems.get(currency.getId());
				Long inventory = inventoryItems.get(currency.getId());
				// older saved states have no kit map
				Long kit = forestryKitItems == null ? null : forestryKitItems.get(currency.getId());
				if (bank == null && inventory == null && kit == null)
				{
					return null;
				}
				return (bank == null ? 0 : bank) + (inventory == null ? 0 : inventory) + (kit == null ? 0 : kit);
			case VARP:
			case VARBIT:
			case VARBIT_COMPOSITE:
				return varBalances.get(currency.getId());
			default:
				return null;
		}
	}

	public Map<String, Long> getBankMaterials()
	{
		// older saved states have no material maps
		if (bankMaterials == null)
		{
			bankMaterials = new HashMap<>();
		}
		return bankMaterials;
	}

	public Map<String, Long> getInventoryMaterials()
	{
		if (inventoryMaterials == null)
		{
			inventoryMaterials = new HashMap<>();
		}
		return inventoryMaterials;
	}

	public Map<String, Long> getLogBasketMaterials()
	{
		if (logBasketMaterials == null)
		{
			logBasketMaterials = new HashMap<>();
		}
		return logBasketMaterials;
	}

	/** Adds to the Forestry kit's count; bark earned with the kit in the inventory goes straight in. */
	public void addToForestryKit(String currency, long amount)
	{
		if (forestryKitItems == null)
		{
			// older saved states have no kit map
			forestryKitItems = new HashMap<>();
		}
		forestryKitItems.merge(currency, amount, Long::sum);
		manualBalances.remove(currency);
	}

	/** Amount of a material in the bank, inventory and log basket, or null before any was seen. */
	public Long materialOf(String name)
	{
		Long bank = getBankMaterials().get(name);
		Long inventory = getInventoryMaterials().get(name);
		Long basket = getLogBasketMaterials().get(name);
		if (bank == null && inventory == null && basket == null)
		{
			return null;
		}
		return (bank == null ? 0 : bank) + (inventory == null ? 0 : inventory) + (basket == null ? 0 : basket);
	}

	/** Value of a {@link Currency.Source#VARBIT_COMPOSITE} currency from its two varbits. */
	public static long compositeValue(Currency currency, int base, int extra)
	{
		return base + (long) currency.getCompositeFactor() * extra;
	}

	/** Whether the plugin can keep this currency up to date by itself. */
	public static boolean isTracked(Currency currency)
	{
		switch (currency.getSource())
		{
			case ITEM:
				return currency.getItemId() != null;
			case VARP:
			case VARBIT:
				return currency.getVarId() != null;
			case VARBIT_COMPOSITE:
				return currency.getVarIds() != null && currency.getVarIds().length == 2 && currency.getCompositeFactor() != null;
			default:
				return false;
		}
	}
}

package com.rewardshopplanner.ui;

import com.rewardshopplanner.data.Currency;
import java.awt.image.BufferedImage;

/**
 * Supplies item sprites to the panel. Images may load asynchronously; {@code onLoaded} is run
 * once the image is ready so the slot can repaint.
 */
public interface ItemIcons
{
	/** The sprite for an item, or null when there is none. */
	BufferedImage get(int itemId, Runnable onLoaded);

	/** A game sprite (a spell icon), or null until it has loaded. */
	default BufferedImage sprite(int spriteId, Runnable onLoaded)
	{
		return null;
	}

	/** The icon standing for a currency: its item, its stand-in item or its sprite; null if none. */
	default BufferedImage currency(Currency currency, Runnable onLoaded)
	{
		if (currency.getIconItem() != null)
		{
			return get(currency.getIconItem(), onLoaded);
		}
		return currency.getIconSpriteId() == null ? null : sprite(currency.getIconSpriteId(), onLoaded);
	}
}

package com.rewardshopplanner.ui;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One collection log slot in the item grid, drawn like the in-game log: full colour when owned,
 * faded when missing, with a gold frame when it is part of the goal.
 */
class ItemSlot extends JComponent
{
	static final int WIDTH = 38;
	static final int HEIGHT = 36;
	private static final Color GOAL = ColorScheme.BRAND_ORANGE;
	private static final Color HOVER = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	private static final Color SELL_BACK = new Color(0x2a9d3a);

	private final BufferedImage icon;
	private final String fallbackText;
	private final boolean owned;
	private final boolean wanted;
	private final boolean needsChoice;
	private final boolean sellBack;
	private boolean hover;

	ItemSlot(BufferedImage icon, String name, boolean owned, boolean wanted, boolean needsChoice, boolean sellBack)
	{
		this.icon = icon;
		this.fallbackText = initials(name);
		this.owned = owned;
		this.wanted = wanted;
		this.needsChoice = needsChoice;
		this.sellBack = sellBack;
		setPreferredSize(new Dimension(WIDTH, HEIGHT));
		setCursor(Cursor.getPredefinedCursor(owned ? Cursor.DEFAULT_CURSOR : Cursor.HAND_CURSOR));
		addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				hover = false;
				repaint();
			}
		});
	}

	@Override
	public javax.swing.JToolTip createToolTip()
	{
		return Tooltips.create(this);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();

		g.setColor(hover ? HOVER : ColorScheme.DARKER_GRAY_COLOR);
		g.fillRoundRect(1, 1, w - 2, h - 2, 6, 6);

		if (!owned)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, wanted ? 0.55f : 0.3f));
		}
		if (icon != null)
		{
			g.drawImage(icon, (w - icon.getWidth()) / 2, (h - icon.getHeight()) / 2, null);
		}
		else
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(Color.WHITE);
			FontMetrics fm = g.getFontMetrics();
			g.drawString(fallbackText, (w - fm.stringWidth(fallbackText)) / 2, (h + fm.getAscent()) / 2 - 2);
		}
		g.setComposite(AlphaComposite.SrcOver);

		if (wanted && !owned)
		{
			g.setColor(GOAL);
			g.setStroke(new BasicStroke(2f));
			g.drawRoundRect(2, 2, w - 4, h - 4, 6, 6);
		}
		if (needsChoice)
		{
			g.setColor(GOAL);
			g.fillOval(w - 12, 3, 9, 9);
			g.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g.setFont(FontManager.getRunescapeSmallFont());
			g.drawString("?", w - 10, 11);
		}
		if (sellBack && !owned)
		{
			// green badge with a return arrow: sold back to the shop once logged
			int x = 3;
			int y = h - 13;
			g.setColor(SELL_BACK);
			g.fillOval(x, y, 10, 10);
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(1.2f));
			g.drawArc(x + 3, y + 2, 5, 5, 270, 270);
			g.drawLine(x + 5, y + 7, x + 3, y + 7);
			g.drawLine(x + 3, y + 7, x + 4, y + 5);
		}
		g.dispose();
	}

	private static String initials(String name)
	{
		StringBuilder out = new StringBuilder();
		for (String word : name.split("[^A-Za-z]+"))
		{
			if (!word.isEmpty() && out.length() < 2)
			{
				out.append(Character.toUpperCase(word.charAt(0)));
			}
		}
		return out.toString();
	}
}

